def within_limits(values, max_length, low, high):
    if len(values) > max_length:
        return False
    for value in values:
        if value < low or value > high:
            return False
    return True

print(within_limits([], 0, -2, 2))
print(within_limits([2, 2], 1, -2, 2))
print(within_limits([3], 3, -2, 2))
print(within_limits([-2, 2], 2, -2, 2))

def first_negative_index(values):
    i = 0
    while i < len(values):
        if values[i] < 0:
            return i
        i += 1
    return -1

print(first_negative_index([]))
print(first_negative_index([0, 3]))
print(first_negative_index([2, -1, -4]))
